import { coverageList } from './library/index.js';

const HEADER = [
  '# M library coverage',
  '',
  'This file is generated by `npm run docs:coverage` from `src/core/m/library/index.js`. Do not edit it by hand.',
  '',
  'Status meanings:',
  '',
  '- `full`: implemented to the documented signature. The commonly used functions have unit tests; the rest are exercised only through the shared helpers.',
  '- `partial`: implemented with known gaps described in `docs/observations.md`.',
  '- `unsupported`: present only so that a query using it stops with a clear error naming the function.',
  '',
  'None of these has been compared against real Excel output yet. The checks that must be run in Excel are listed in `docs/observations.md`.',
  ''
];

export function coverageDocument() {
  const list = coverageList();
  const counts = { full: 0, partial: 0, unsupported: 0 };
  for (const e of list) counts[e.status] = (counts[e.status] || 0) + 1;
  const lines = [...HEADER, `${list.length} entries: ${counts.full} full, ${counts.partial || 0} partial, ${counts.unsupported || 0} unsupported.`, '', '| Function | Status |', '| --- | --- |'];
  for (const e of list) lines.push(`| \`${e.name}\` | ${e.status} |`);
  return `${lines.join('\n')}\n`;
}
